import base64
import json
import os
from pathlib import Path
from typing import Any, Dict, Optional

import boto3


def _load_image_bytes(image_path: str) -> bytes:
    return Path(image_path).expanduser().read_bytes()


def _image_bytes_from_input(image_input: str) -> bytes:
    if image_input.startswith("data:"):
        _, data = image_input.split(",", 1)
        return base64.b64decode(data)
    if Path(image_input).expanduser().exists():
        return _load_image_bytes(image_input)
    try:
        return base64.b64decode(image_input, validate=True)
    except Exception as exc:
        raise ValueError("image_input must be a file path, data URI, or base64-encoded image string") from exc


def check_image_for_unsafe_content(image_input: str, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Check an image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Returns a dictionary with:
      - unsafe: bool
      - risk_score: float
      - labels: list of detected labels with confidence
      - moderation_flags: list of sensitive category matches
      - raw_response: original Rekognition response subset
    """
    image_bytes = _image_bytes_from_input(image_input)
    rekognition = boto3.client("rekognition", region_name=region_name or os.getenv("AWS_REGION"))

    response = rekognition.detect_labels(
        Image={"Bytes": image_bytes},
        MinConfidence=70.0,
    )

    labels = []
    moderation_flags = []
    risk_score = 0.0

    sensitive_keywords = {
        "Explicit Nudity": 0.95,
        "Nudity": 0.85,
        "Sexual Activity": 0.98,
        "Sexual Content": 0.90,
        "Violence": 0.80,
        "Weapon": 0.70,
        "Gun": 0.80,
        "Knife": 0.70,
        "Blood": 0.75,
        "Drugs": 0.85,
        "Alcohol": 0.50,
        "Tobacco": 0.50,
        "Hate Symbol": 0.95,
        "Emblem": 0.20,
        "Fire": 0.35,
        "Explosion": 0.90,
        "Fight": 0.85,
        "Body Part": 0.10,
    }

    for label in response.get("Labels", []):
        name = label.get("Name", "")
        confidence = float(label.get("Confidence", 0.0))
        labels.append({"name": name, "confidence": confidence})

        for keyword, weight in sensitive_keywords.items():
            if keyword.lower() in name.lower():
                moderation_flags.append({"category": keyword, "label": name, "confidence": confidence})
                risk_score = max(risk_score, (confidence / 100.0) * weight)

    # Heuristic risk from combinations
    label_names = {item["name"].lower() for item in labels}
    if ("person" in label_names or "human" in label_names) and any(
        k in label_names for k in {"weapon", "gun", "knife"}
    ):
        moderation_flags.append(
            {"category": "Potential Violence/Weapon Presence", "label": "person + weapon", "confidence": 0.9}
        )
        risk_score = max(risk_score, 0.9)

    unsafe = risk_score >= 0.75 or any(
        flag["category"] in {"Explicit Nudity", "Sexual Activity", "Potential Violence/Weapon Presence", "Hate Symbol"}
        for flag in moderation_flags
    )

    return {
        "unsafe": unsafe,
        "risk_score": round(risk_score, 3),
        "labels": labels,
        "moderation_flags": moderation_flags,
        "raw_response": {
            "labels": response.get("Labels", []),
            "label_model_version": response.get("LabelModelVersion"),
        },
    }
